/* CommerceForge Dev Docs — Global Styles */
:root {
  --bg-primary: #0d1117;
  --bg-secondary: #161b22;
  --bg-tertiary: #1c2333;
  --bg-card: #161b22;
  --border-color: #30363d;
  --border-subtle: #21262d;
  --text-primary: #e6edf3;
  --text-secondary: #8b949e;
  --text-muted: #6e7681;
  --accent: #00e5a0;
  --accent-hover: #00cc8e;
  --accent-cyan: #00d4ff;
  --accent-blue: #475F91;
  --link-color: #58a6ff;
  --code-bg: #0d1117;
  --code-border: #30363d;
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', 'Consolas', monospace;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow-card: 0 1px 3px rgba(0,0,0,0.3), 0 0 0 1px var(--border-color);
  --shadow-glow: 0 0 20px rgba(0,229,160,0.1);
  --transition: 0.2s ease;
  --max-width: 1200px;
  --sidebar-width: 260px;
}

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-sans);
  background: var(--bg-primary);
  color: var(--text-primary);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

a { color: var(--link-color); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--accent); }

img { max-width: 100%; display: block; }

code, pre { font-family: var(--font-mono); }

/* Top Navigation */
.top-nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: rgba(13,17,23,0.85);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid var(--border-color);
  padding: 0 24px;
}

.nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 56px;
}

.nav-logo {
  font-weight: 700;
  font-size: 1.05rem;
  color: var(--text-primary);
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-logo svg { width: 24px; height: 24px; }

.nav-links {
  display: flex;
  align-items: center;
  gap: 4px;
  list-style: none;
}

.nav-links a {
  color: var(--text-secondary);
  font-size: 0.875rem;
  font-weight: 500;
  padding: 6px 12px;
  border-radius: 6px;
  transition: all var(--transition);
}

.nav-links a:hover, .nav-links a.active {
  color: var(--text-primary);
  background: var(--bg-tertiary);
}

.nav-utils {
  display: flex;
  align-items: center;
  gap: 8px;
}

.nav-search {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 12px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 6px;
  color: var(--text-muted);
  font-size: 0.8rem;
  cursor: pointer;
  transition: border-color var(--transition);
}

.nav-search:hover { border-color: var(--text-muted); }

.nav-login {
  padding: 6px 14px;
  font-size: 0.8rem;
  font-weight: 500;
  color: var(--text-primary);
  background: transparent;
  border: 1px solid var(--border-color);
  border-radius: 6px;
  cursor: pointer;
  transition: all var(--transition);
}

.nav-login:hover { border-color: var(--text-secondary); background: var(--bg-secondary); }

.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  color: var(--text-primary);
  cursor: pointer;
  padding: 4px;
}

/* Hero Section */
.hero {
  padding: 80px 24px 60px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  left: 50%;
  transform: translateX(-50%);
  width: 800px;
  height: 800px;
  background: radial-gradient(circle, rgba(0,229,160,0.06) 0%, transparent 70%);
  pointer-events: none;
}

.hero h1 {
  font-size: clamp(2rem, 4vw, 3rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
  position: relative;
}

.hero p {
  font-size: clamp(0.95rem, 1.5vw, 1.1rem);
  color: var(--text-secondary);
  max-width: 680px;
  margin: 0 auto 32px;
  line-height: 1.7;
  position: relative;
}

.hero-ctas {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  justify-content: center;
  position: relative;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  background: var(--accent);
  color: #0d1117;
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: 6px;
  border: none;
  cursor: pointer;
  transition: all var(--transition);
}

.btn-primary:hover { background: var(--accent-hover); color: #0d1117; transform: translateY(-1px); }

.btn-secondary {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 20px;
  background: transparent;
  color: var(--text-primary);
  font-weight: 600;
  font-size: 0.875rem;
  border-radius: 6px;
  border: 1px solid var(--border-color);
  cursor: pointer;
  transition: all var(--transition);
}

.btn-secondary:hover { border-color: var(--accent); color: var(--accent); transform: translateY(-1px); }

/* Section Layouts */
.section {
  padding: 64px 24px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.section-header {
  margin-bottom: 40px;
}

.section-header h2 {
  font-size: 1.75rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
}

.section-header p {
  color: var(--text-secondary);
  font-size: 1rem;
  max-width: 640px;
}

.section-divider {
  border: none;
  border-top: 1px solid var(--border-subtle);
  margin: 0 24px;
  max-width: var(--max-width);
  margin-left: auto;
  margin-right: auto;
}

/* Cards */
.card-grid {
  display: grid;
  gap: 16px;
}

.card-grid-3 { grid-template-columns: repeat(3, 1fr); }
.card-grid-2 { grid-template-columns: repeat(2, 1fr); }
.card-grid-4 { grid-template-columns: repeat(4, 1fr); }

.card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
  position: relative;
}

.card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-glow);
  transform: translateY(-2px);
}

.card-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
  color: var(--accent);
  font-size: 1.2rem;
}

.card h3 {
  font-size: 1.05rem;
  font-weight: 600;
  margin-bottom: 8px;
}

.card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

.card-link {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--accent);
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.card-link:hover { color: var(--accent-hover); gap: 8px; }

/* Product Cards (Home) */
.product-card {
  border-top: 3px solid var(--accent);
}

.product-card:nth-child(2) { border-top-color: var(--accent-cyan); }
.product-card:nth-child(3) { border-top-color: var(--accent-blue); }

.product-card .card-icon { font-size: 1.5rem; }
.product-card:nth-child(2) .card-icon { color: var(--accent-cyan); }
.product-card:nth-child(3) .card-icon { color: var(--accent-blue); }

/* CLI Setup Section */
.cli-section {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  border: 1px solid var(--border-color);
  padding: 40px;
  margin-top: 20px;
}

.accordion-item {
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  margin-bottom: 8px;
  overflow: hidden;
  background: var(--bg-primary);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.95rem;
  user-select: none;
  transition: background var(--transition);
}

.accordion-header:hover { background: var(--bg-tertiary); }

.accordion-header .chevron {
  transition: transform var(--transition);
  color: var(--text-muted);
}

.accordion-item.active .accordion-header { background: var(--bg-tertiary); }
.accordion-item.active .accordion-header .chevron { transform: rotate(180deg); }

.accordion-body {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease;
}

.accordion-item.active .accordion-body {
  max-height: 600px;
}

.accordion-content {
  padding: 20px;
  border-top: 1px solid var(--border-color);
}

.step {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

.step-num {
  flex-shrink: 0;
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--accent);
  color: #0d1117;
  font-size: 0.75rem;
  font-weight: 700;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-top: 2px;
}

.step p {
  color: var(--text-secondary);
  font-size: 0.875rem;
}

/* Package Manager Tabs */
.pkg-tabs {
  display: flex;
  gap: 2px;
  margin-bottom: 0;
  background: var(--bg-tertiary);
  border-radius: var(--radius) var(--radius) 0 0;
  padding: 4px 4px 0;
}

.pkg-tab {
  padding: 8px 16px;
  font-size: 0.8rem;
  font-weight: 600;
  font-family: var(--font-mono);
  color: var(--text-muted);
  cursor: pointer;
  border: none;
  background: transparent;
  border-radius: 6px 6px 0 0;
  transition: all var(--transition);
}

.pkg-tab:hover { color: var(--text-secondary); }
.pkg-tab.active { color: var(--accent); background: var(--code-bg); }

.code-block {
  background: var(--code-bg);
  border: 1px solid var(--code-border);
  border-radius: 0 0 var(--radius) var(--radius);
  padding: 16px 20px;
  font-family: var(--font-mono);
  font-size: 0.85rem;
  color: var(--accent);
  overflow-x: auto;
  position: relative;
}

.code-block.rounded {
  border-radius: var(--radius);
}

.code-block .prompt { color: var(--text-muted); }
.code-block .cmd { color: var(--accent); }

.copy-btn {
  position: absolute;
  top: 8px;
  right: 8px;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: 4px;
  color: var(--text-muted);
  padding: 4px 8px;
  font-size: 0.7rem;
  cursor: pointer;
  transition: all var(--transition);
}

.copy-btn:hover { color: var(--text-primary); border-color: var(--text-muted); }

/* Launch CTAs */
.launch-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.launch-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 32px;
  transition: all var(--transition);
}

.launch-card:hover { border-color: var(--accent); }

.launch-card h3 {
  font-size: 1.15rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.launch-card p {
  color: var(--text-secondary);
  font-size: 0.875rem;
  line-height: 1.6;
  margin-bottom: 16px;
}

/* Community Resources */
.community-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.community-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
  cursor: pointer;
}

.community-card:hover { border-color: var(--accent); transform: translateY(-2px); }

.community-card h4 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.community-card p {
  color: var(--text-muted);
  font-size: 0.8rem;
}

/* Docs Layout (Sidebar) */
.docs-layout {
  display: flex;
  min-height: calc(100vh - 56px);
}

.sidebar {
  width: var(--sidebar-width);
  border-right: 1px solid var(--border-color);
  background: var(--bg-secondary);
  padding: 24px 0;
  position: sticky;
  top: 56px;
  height: calc(100vh - 56px);
  overflow-y: auto;
  flex-shrink: 0;
  transition: width 0.3s ease, padding 0.3s ease, opacity 0.3s ease;
}

.sidebar.collapsed {
  width: 0;
  padding: 0;
  overflow: hidden;
  opacity: 0;
}

.sidebar-toggle {
  position: fixed;
  left: var(--sidebar-width);
  top: 72px;
  z-index: 50;
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-left: none;
  border-radius: 0 6px 6px 0;
  padding: 8px 6px;
  cursor: pointer;
  color: var(--text-muted);
  transition: all 0.3s ease;
  display: flex;
  align-items: center;
}

.sidebar-toggle.collapsed-pos {
  left: 0;
}

.sidebar-toggle:hover { color: var(--text-primary); background: var(--bg-tertiary); }

.sidebar-section {
  padding: 0 16px;
  margin-bottom: 24px;
}

.sidebar-section-title {
  font-size: 0.7rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--text-muted);
  margin-bottom: 8px;
  padding: 0 8px;
}

.sidebar-link {
  display: block;
  padding: 6px 8px;
  font-size: 0.85rem;
  color: var(--text-secondary);
  border-radius: 4px;
  transition: all var(--transition);
}

.sidebar-link:hover { color: var(--text-primary); background: var(--bg-tertiary); }
.sidebar-link.active { color: var(--accent); background: rgba(0,229,160,0.08); }

.docs-content {
  flex: 1;
  min-width: 0;
  padding: 40px;
  max-width: 900px;
}

.docs-content .hero {
  padding: 40px 0 32px;
  text-align: left;
}

.docs-content .hero h1 { font-size: 2rem; }
.docs-content .hero p { margin: 0; }

.docs-section { margin-bottom: 48px; }

.docs-section h2 {
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 8px;
  padding-top: 16px;
}

.docs-section > p {
  color: var(--text-secondary);
  margin-bottom: 24px;
  font-size: 0.95rem;
}

/* Protocol Actors Diagram */
.actors-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

.actor-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  text-align: center;
  position: relative;
  transition: all var(--transition);
}

.actor-card:hover { border-color: var(--accent); }

.actor-icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: var(--bg-tertiary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
  font-size: 1.2rem;
  color: var(--accent);
}

.actor-card h4 { font-size: 0.95rem; margin-bottom: 4px; }
.actor-card p { color: var(--text-muted); font-size: 0.8rem; }

.actor-connector {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin: 16px 0;
  color: var(--text-muted);
  font-size: 0.8rem;
}

.actor-connector::before, .actor-connector::after {
  content: '';
  flex: 1;
  height: 1px;
  background: var(--border-color);
}

/* How It Works */
.how-it-works-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin: 24px 0;
}

/* Badge */
.badge {
  display: inline-block;
  padding: 3px 10px;
  font-size: 0.7rem;
  font-weight: 600;
  border-radius: 20px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.badge-coming-soon {
  background: rgba(255,193,7,0.15);
  color: #ffc107;
  border: 1px solid rgba(255,193,7,0.3);
}

/* Footer */
.footer {
  border-top: 1px solid var(--border-color);
  padding: 48px 24px 32px;
  margin-top: 64px;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}

.footer-col h4 {
  font-size: 0.8rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 12px;
}

.footer-col a {
  display: block;
  font-size: 0.85rem;
  color: var(--text-secondary);
  padding: 3px 0;
}

.footer-col a:hover { color: var(--text-primary); }

.footer-bottom {
  max-width: var(--max-width);
  margin: 32px auto 0;
  padding-top: 24px;
  border-top: 1px solid var(--border-subtle);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.8rem;
  color: var(--text-muted);
}

/* Best Practices */
.practices-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 12px;
}

.practice-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius);
  padding: 20px;
  transition: all var(--transition);
}

.practice-card:hover { border-color: var(--accent); }

.practice-card h4 {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 6px;
}

.practice-card p {
  color: var(--text-muted);
  font-size: 0.8rem;
  line-height: 1.5;
}

/* Theming Highlights */
.theming-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
  margin: 24px 0;
}

.theme-feature {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
}

.theme-feature:hover { border-color: var(--accent); }

.theme-feature h4 { font-size: 0.95rem; font-weight: 600; margin-bottom: 6px; }
.theme-feature p { color: var(--text-secondary); font-size: 0.85rem; }

/* Support page */
.support-hero {
  background: linear-gradient(135deg, var(--bg-secondary), var(--bg-tertiary));
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 48px;
  text-align: center;
  margin-bottom: 48px;
}

.support-hero h1 { font-size: 2rem; margin-bottom: 12px; }
.support-hero p { color: var(--text-secondary); max-width: 500px; margin: 0 auto 24px; }

.support-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin: 24px 0;
}

.support-card {
  background: var(--bg-card);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 24px;
  transition: all var(--transition);
}

.support-card:hover { border-color: var(--accent); }
.support-card h4 { font-size: 0.95rem; margin-bottom: 8px; }
.support-card p { color: var(--text-muted); font-size: 0.8rem; line-height: 1.5; }
.support-card ul { list-style: none; margin-top: 8px; }
.support-card ul li {
  font-size: 0.8rem;
  color: var(--text-secondary);
  padding: 3px 0;
}

.contact-section {
  background: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 40px;
  text-align: center;
  margin-top: 32px;
}

.contact-section h3 { font-size: 1.2rem; margin-bottom: 8px; }
.contact-section p { color: var(--text-secondary); margin-bottom: 20px; font-size: 0.9rem; }

/* Mobile Responsive */
@media (max-width: 1024px) {
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .launch-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
  .actors-grid { grid-template-columns: repeat(2, 1fr); }
  .practices-grid { grid-template-columns: repeat(2, 1fr); }
  .support-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-utils .nav-search { display: none; }
  .mobile-menu-btn { display: block; }

  .mobile-nav {
    display: none;
    position: fixed;
    top: 56px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--bg-primary);
    z-index: 99;
    padding: 24px;
  }

  .mobile-nav.open { display: block; }

  .mobile-nav a {
    display: block;
    padding: 12px 0;
    font-size: 1.1rem;
    color: var(--text-secondary);
    border-bottom: 1px solid var(--border-subtle);
  }

  .mobile-nav a:hover { color: var(--text-primary); }

  .hero { padding: 48px 20px 40px; }
