/* Mobile Responsive */
@media (max-width: 1024px) {
  .card-grid-3 { grid-template-columns: repeat(2, 1fr); }
  .card-grid-4 { grid-template-columns: repeat(2, 1fr); }
  .community-grid { grid-template-columns: repeat(2, 1fr); }
  .launch-grid { grid-template-columns: 1fr; }
  .footer-inner { grid-template-columns: repeat(2, 1fr); }
  .actors-grid { grid-template-columns: repeat(2, 1fr); }
  .practices-grid { grid-template-columns: repeat(2, 1fr); }
  .support-grid { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; }
  .nav-utils .nav-search { display: none; }
  .mobile-menu-btn { display: block; }

  .mobile-nav {
    display: none;
    position: fixed;
    top: 56px;
    left: 0;
    right: 0;
    bottom: 0;
    background: var(--bg-primary);
    z-index: 99;
    padding: 24px;
  }

  .mobile-nav.open { display: block; }

  .mobile-nav a {
    display: block;
    padding: 12px 0;
    font-size: 1.1rem;
    color: var(--text-secondary);
    border-bottom: 1px solid var(--border-subtle);
  }

  .mobile-nav a:hover { color: var(--text-primary); }

  .hero { padding: 48px 20px 40px; }
  .hero h1 { font-size: 1.75rem; }

  .section { padding: 40px 20px; }

  .card-grid-3, .card-grid-2, .card-grid-4 { grid-template-columns: 1fr; }
  .community-grid { grid-template-columns: 1fr; }
  .actors-grid { grid-template-columns: 1fr; }
  .practices-grid { grid-template-columns: 1fr; }
  .support-grid { grid-template-columns: 1fr; }

  .cli-section { padding: 24px 16px; }

  .footer-inner { grid-template-columns: 1fr 1fr; gap: 24px; }
  .footer-bottom { flex-direction: column; gap: 8px; }

  .sidebar { display: none; }
  .sidebar-toggle { display: none; }
  .docs-content { padding: 20px; }

  .theming-grid { grid-template-columns: 1fr; }
  .how-it-works-grid { grid-template-columns: 1fr; }

  .hero-ctas { flex-direction: column; align-items: center; }
}

@media (max-width: 480px) {
  .hero h1 { font-size: 1.5rem; }
  .footer-inner { grid-template-columns: 1fr; }
}
